s2 = szUse ? szOne : sz2i
s1       = szUse ? szOne : sz1i
s3       = szUse ? szOne : sz3i
szBos    = szUse ? szOne : szBosi
szMss    = szUse ? szOne : szMssi
szMssTag = szUse ? szOne : szMtgi
szFifth  = szUse ? szOne : szFfti
